const data = $input.all().map(item => item.json);

function getProp(props, name) {
  const p = (props || []).find(p => p.name === name);
  return p ? p.value : "";
}

const byScoreRange = {
  "Гарячі (score >= 50)": 0,
  "Холодні (score < 50)": 0,
  "Без оцінки (score = 0)": 0
};

let newLeadsCount = 0;
const now = Math.floor(Date.now() / 1000);
const weekAgo = now - 7 * 24 * 60 * 60;

for (const lead of data) {
  const score = lead.lead_score || 0;

  if (score >= 50) {
    byScoreRange["Гарячі (score >= 50)"]++;
  } else if (score > 0) {
    byScoreRange["Холодні (score < 50)"]++;
  } else {
    byScoreRange["Без оцінки (score = 0)"]++;
  }

  if (lead.created_time && lead.created_time >= weekAgo) {
    newLeadsCount++;
  }
}

const result = {
  total_leads: data.length,
  new_leads_count: newLeadsCount,
  by_stage: byScoreRange,
  by_owner: {}
};

return [{ json: result }];

